Translate("deDE", "hall-of-thanes", {
	title = "Hall of Thanes",
	aliases = { "The Hall of Thanes" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Hall of Thanes liegt in den Höhlen unter {link:old-ironforge}Old Ironforge{/link}, tief unter dem Hohen Sitz. Sie ist ein Ort der Gräber und Gewölbe, an dem die großen {link:dwarves}Zwerge{/link} aus Ironforges Vergangenheit zur Ruhe gebettet und die Schätze seiner Könige versiegelt wurden. Über Generationen betraten nur ihre Hüter die Hallen. Nun sind die Toten ruhelos, und die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} sind von unten eingedrungen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wann der erste Than in diesen Hallen zur Ruhe gebettet wurde. Die Gewölbe an ihrer tiefsten Stelle heißen die Reliquienkammer der Könige. Unter den dort verwahrten Reliquien befand sich eine Steintafel aus den Tagen nach dem Krieg der drei Klans, als Madoran der erste König der Bronzebeards in {link:ironforge}Ironforge{/link} wurde: der Friedensvertrag zwischen den Bronzebeards und den Wildhammers, den die {link:dark-iron-dwarves}Dunkeleisen{/link} nicht unterzeichnen wollten. Eine andere Kammer, Anvilmar's Rest, birgt das Grab eines Thans namens {link:faldrim-anvilmar}Faldrim Anvilmar{/link}.]=],
		},
		{
			title = "Der Einfall",
			text = [=[{link:earthseer-farsen}Erdseher Farsen{/link}, ein Wildhammer zu Besuch in {link:dun-morogh}Dun Morogh{/link}, erkannte die Gefahr als Erster. Spione der {link:dark-iron-dwarves}Dunkeleisen{/link} waren ins Land gekommen, und eine Karte, die man ihren Toten abnahm, zeigte Tunnel, die sich unter {link:ironforge}Ironforge{/link} trafen. Die Dunkeleisen stiegen in Maulwurfmaschinen in die Gewölbe hinauf. Ihre Plünderer begannen, die Gräber ihrer Erbstücke zu berauben, ihre Ingenieure schleuderten Bomben, und ihre Beschwörer riefen das Feuer herbei. Steingolems gehen an ihrer Seite. Zugleich erwachten die Geister der Toten, zornig und gequält, und begannen, ihre eigenen Hallen heimzusuchen.]=],
		},
		{
			title = "Bosse",
			text = [=[• {b}{link:faldrim-anvilmar}Faldrim Anvilmar{/link}{/b}, ein Than aus alter Zeit, dessen Geist keine Ruhe findet, verzehrt von einem uralten Groll.
• {b}{link:magmatus}Magmatus{/link}{/b}, ein Wesen aus lebendem Feuer, das an der Seite eines Beschwörers der {link:dark-iron-dwarves}Dunkeleisen{/link} kämpft.
• {b}Plunder{/b}, ein Elementar, das durch eine Halle der Gewölbe streift und Eindringlinge beiseiteschleudert.
• {b}{link:durgen-dirgehammer}Durgen Dirgehammer{/link}{/b}, der Befehlshaber des Einfalls der Dunkeleisen, bewacht von Golems in den unteren Gewölben.]=],
		},
		{
			title = "In der heutigen Zeit",
			text = [=[Die Hüter der Gräber wollen nicht in die Halle hinabsteigen, bevor die Toten Ruhe gefunden haben. Ein {link:gnomes}Gnom{/link}, der behauptet, er habe die Gewölbe bewacht, will die Erbstücke wieder hinaufgetragen sehen und sagt, er werde sie verzeichnen. {link:earthseer-farsen}Erdseher Farsen{/link} bittet um Freiwillige, die hinabsteigen, den Befehlshaber der {link:dark-iron-dwarves}Dunkeleisen{/link} finden und seinen Kopf zum König bringen. König {link:magni-bronzebeard}Magni Bronzebeard{/link} hat versprochen, dass die Breschen versiegelt und die unteren Hallen befestigt werden, sobald die Eindringlinge fort sind, damit kein Feind je wieder auf diesem Weg kommen kann.]=],
		},
	},
})

Translate("deDE", "faldrim-anvilmar", {
	title = "Faldrim Anvilmar",
	subtitle = "Der ruhelose Than",
	found = "Anvilmar's Rest, in der Hall of Thanes",
	allegiance = "Die Toten von Ironforge",
	aliases = { "Faldrim" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Faldrim Anvilmar war ein Than von {link:ironforge}Ironforge{/link}, zur Ruhe gebettet in der Kammer namens Anvilmar's Rest. Als die {link:dark-iron-dwarves}Dunkeleisen{/link} in die Gewölbe einbrachen, erwachte sein Geist mit den anderen, und er erwachte nicht in Frieden. Er wandelt durch seine Halle, verzehrt von einem uralten Groll, greift den Geist der Lebenden an und belegt jene mit einem Fluch, die sich ihm entgegenstellen. Der Geist eines Mannes, der ihm diente, fleht darum, dass jemand seinen Than endlich ruhen lässt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Faldrim trägt den Namen Anvilmar, den Namen des Hochkönigs, unter dem einst alle {link:dwarves}Zwerge{/link} vereint waren. Was ihn mit diesem König verband und welcher Groll ihn nun festhält, sagt keine Chronik.]=],
		},
	},
	mentions = {
		{ text = "Ein uralter Groll" },
	},
	bonds = {
		{ id = "durgen-dirgehammer", name = "Durgen Dirgehammer", note = "der Eindringling in seinem Grab" },
	},
})

Translate("deDE", "magmatus", {
	title = "Magmatus",
	subtitle = "Feuer der Dunkeleisen",
	found = "Die Hall of Thanes",
	allegiance = "Dunkeleisenzwerge",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Magmatus ist ein Wesen aus lebendem Feuer, das mit den {link:dark-iron-dwarves}Dunkeleisen{/link} in die {link:hall-of-thanes}Hall of Thanes{/link} gekommen ist. Ein Beschwörer der Dunkeleisen steht an seiner Seite, und die Flammen, die aus ihm strömen, überspülen jeden in seiner Nähe. Die Dunkeleisen dienen den Herren des Feuers seit dem Fall ihrer Stadt {link:ruins-of-thaurissan}Thaurissan{/link}, und ihre Beschwörer bringen das Feuer mit, wohin sie auch gehen. In den Gräbern der Thane, zwischen dem alten Stein von {link:ironforge}Ironforge{/link}, brennt Magmatus wie ein Zeichen dafür, wer gekommen ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Magmatus zeigt, dass der Einfall der {link:dark-iron-dwarves}Dunkeleisen{/link} kein bloßer Diebeszug ist. Die unter {link:ironforge}Ironforge{/link} eindrangen, brachten die Macht ihrer Herren mit sich.]=],
		},
	},
})

